import{_ as n,c as s,o as t,a0 as e}from"./chunks/framework.CAcMrZkh.js";const h=JSON.parse('{"title":"BearPlan.NET 后端介绍","description":"BearPlan.NET 后端工程介绍：基于 .NET + SqlSugar 的严格分层架构，依赖自上而下，覆盖 Api 入口、Infrastructure 装配层、业务服务、仓储、实体与业务中立的 Core 核心库。","frontmatter":{"title":"BearPlan.NET 后端介绍","description":"BearPlan.NET 后端工程介绍：基于 .NET + SqlSugar 的严格分层架构，依赖自上而下，覆盖 Api 入口、Infrastructure 装配层、业务服务、仓储、实体与业务中立的 Core 核心库。"},"headers":[],"relativePath":"bearplan/dotnet.md","filePath":"bearplan/dotnet.md"}'),r={name:"bearplan/dotnet.md"};function l(p,a,o,i,d,c){return t(),s("div",null,a[0]||(a[0]=[e(`<h1 id="bearplan-net-介绍" tabindex="-1">BearPlan.NET 介绍 <a class="header-anchor" href="#bearplan-net-介绍" aria-label="Permalink to &quot;BearPlan.NET 介绍&quot;">​</a></h1><blockquote><p>BearPlan.NET 是 BearPlan 的后端工程，基于 .NET 10 + SqlSugar 的分层架构。本文聚焦后端的<strong>整体骨架与分层职责</strong>，帮助读者建立全局认知：一个请求怎么流转、各模块负责什么、依赖方向如何约束。</p></blockquote><p>项目整体背景见 <a href="/bearplan/first.html">序言</a>；通用核心库 <code>BearPlan.Core</code> 的能力清单见 <a href="/bearplan/introduction.html">Core 介绍</a>；后端部署见 <a href="/bearplan/deploy-api.html">后端部署</a>。本文不重复这些内容。</p><h2 id="分层架构" tabindex="-1">分层架构 <a class="header-anchor" href="#分层架构" aria-label="Permalink to &quot;分层架构&quot;">​</a></h2><p>BearPlan.NET 按职责严格分层，依赖方向<strong>自上而下</strong>——上层可引用下层，下层不得反向引用上层。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  BearPlan.Api                  应用入口                  │</span></span>
<span class="line"><span>│  路由 · 中间件管道 · 控制器 · Program.cs 装配             │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  BearPlan.Infrastructure      应用装配层（唯一可引用一切）│</span></span>
<span class="line"><span>│  DI 注册 · JWT 鉴权 · ActionFilter · 业务中间件          │</span></span>
<span class="line"><span>│  种子数据 · AOP 实现 · 日志 Sink                         │</span></span>
<span class="line"><span>├──────────────────────┬──────────────────────────────────┤</span></span>
<span class="line"><span>│  Business            │  EventBus / TaskService          │</span></span>
<span class="line"><span>│  业务服务实现         │  事件总线（含微信）· 定时任务     │</span></span>
<span class="line"><span>├──────────────────────┴──────────────────────────────────┤</span></span>
<span class="line"><span>│  IBusiness  /  Models         业务契约 / 请求响应 DTO    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Repository          SqlSugar 仓储扩展 · 工作单元事务    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Entity              数据库实体映射                       │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  BearPlan.Core ⭐    通用框架库（业务中立，独立发布）     │</span></span>
<span class="line"><span>│  BearPlan.Common     项目专属库（业务常量/枚举/实现）     │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="模块职责" tabindex="-1">模块职责 <a class="header-anchor" href="#模块职责" aria-label="Permalink to &quot;模块职责&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td><code>BearPlan.Api</code></td><td>Web 接口入口：路由注册、中间件管道、控制器</td></tr><tr><td><code>BearPlan.Infrastructure</code></td><td>应用装配层：DI 扩展、JWT 鉴权、过滤器、业务中间件、种子数据、AOP/日志实现</td></tr><tr><td><code>BearPlan.Business</code></td><td>业务服务实现</td></tr><tr><td><code>BearPlan.IBusiness</code></td><td>业务服务接口契约</td></tr><tr><td><code>BearPlan.EventBus</code></td><td>事件总线（含微信消息处理）</td></tr><tr><td><code>BearPlan.TaskService</code></td><td>系统定时任务（Quartz）</td></tr><tr><td><code>BearPlan.Repository</code></td><td>SqlSugar 仓储扩展、工作单元事务</td></tr><tr><td><code>BearPlan.Entity</code></td><td>数据库实体映射类</td></tr><tr><td><code>BearPlan.Models</code></td><td>请求 DTO、查询参数、响应模型</td></tr><tr><td><code>BearPlan.Common</code></td><td>项目业务专属：缓存 key、业务枚举、HttpUser、多语言资源、AppConfig</td></tr><tr><td><code>BearPlan.Core</code></td><td>业务无关的通用框架基础设施</td></tr></tbody></table><h3 id="分层依赖关系" tabindex="-1">分层依赖关系 <a class="header-anchor" href="#分层依赖关系" aria-label="Permalink to &quot;分层依赖关系&quot;">​</a></h3><p>理解 BearPlan.NET 的关键在于看清依赖方向：</p><ul><li><strong>Core 是地基</strong>：被 <code>Entity</code> 引用，链式传递到几乎所有项目。Core 本身不依赖任何业务项目。</li><li><strong>Common 是项目专属基座</strong>：与 Core 同处底层，承载 BearPlan 特有的常量与实现，同样被 Entity 引用。</li><li><strong>Infrastructure 是装配层</strong>：<strong>唯一可以「引用一切」的层</strong>（依赖 Entity / IBusiness / Repository / TaskService / EventBus 等），承载让系统跑起来的技术实现。</li><li><strong>Api 是入口</strong>：最顶层，只被自己的 Program.cs 引用，组装所有模块。</li></ul><div class="warning custom-block"><p class="custom-block-title">核心约束</p><p><code>BearPlan.Core</code> <strong>不得引用任何业务项目</strong>（Entity / IBusiness / Repository / 业务实现），保持业务中立，确保可独立编译与发布。</p><p>依赖业务实体的代码（如数据库种子 <code>SeedService</code>、事务 AOP、日志写库 Sink）即使看起来是&quot;框架设施&quot;，也必须放在 <code>Infrastructure</code>，而不能进入 Core——否则会形成循环依赖。</p></div><h2 id="请求链路" tabindex="-1">请求链路 <a class="header-anchor" href="#请求链路" aria-label="Permalink to &quot;请求链路&quot;">​</a></h2><p>一个 HTTP 请求从进入到响应，经过以下层：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP 请求</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Api 层：路由匹配 → 中间件管道（CORS / 限流 / 鉴权）    │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Infrastructure 层：                                    │</span></span>
<span class="line"><span>│   · PermissionHandler（权限校验）                      │</span></span>
<span class="line"><span>│   · AuditLogFilter（审计日志，记录操作）                │</span></span>
<span class="line"><span>│   · ExceptionLogFilter（异常捕获，写日志库）            │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Controller → 调用 Business 服务                        │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Business 层：业务逻辑（可能经 AOP 拦截：缓存/事务）    │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Repository 层：SqlSugar 仓储读写数据库                  │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Entity / Core：实体映射 · 通用模型 · 工具               │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>HTTP 响应（统一格式化）</span></span></code></pre></div><p>关键点：</p><ul><li><strong>鉴权统一在 Infrastructure 的 <code>PermissionHandler</code></strong>：Controller 不写权限判断。</li><li><strong>横切关注点用 AOP / Filter</strong>：缓存、事务、审计日志通过特性声明，不侵入业务代码。</li><li><strong>响应统一格式化</strong>：所有接口返回统一结构，由 Infrastructure 的中间件处理。</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>技术</th></tr></thead><tbody><tr><td><strong>运行时</strong></td><td>.NET 10</td></tr><tr><td><strong>ORM</strong></td><td>SqlSugarCore（支持 MySQL / SQL Server / PostgreSQL / Oracle / SQLite）</td></tr><tr><td><strong>缓存</strong></td><td>StackExchange.Redis</td></tr><tr><td><strong>日志</strong></td><td>Serilog（含 Async / Elasticsearch Sink）</td></tr><tr><td><strong>依赖注入 / AOP</strong></td><td>Autofac（含 DynamicProxy）</td></tr><tr><td><strong>对象映射</strong></td><td>Mapster</td></tr><tr><td><strong>图像处理</strong></td><td>SixLabors.ImageSharp</td></tr><tr><td><strong>任务调度</strong></td><td>Quartz</td></tr><tr><td><strong>鉴权</strong></td><td>JWT Bearer</td></tr><tr><td><strong>API 文档</strong></td><td>Swashbuckle (Swagger)</td></tr></tbody></table><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><p>BearPlan.NET 遵循三条核心原则：</p><ul><li><strong>🏢 分层清晰</strong>：按职责严格分层，避免跨层调用，结构清晰、易扩展。</li><li><strong>🎯 业务中立</strong>：与具体业务无关的框架基础设施沉淀为独立通用库 <code>BearPlan.Core</code>，不绑定任何业务实体，可被任意 .NET 项目复用。</li><li><strong>🧩 开箱即用</strong>：内置权限控制、AOP 拦截、日志、定时任务、缓存、多库适配等常用能力，无需从零搭建。</li></ul><h2 id="关联资源" tabindex="-1">关联资源 <a class="header-anchor" href="#关联资源" aria-label="Permalink to &quot;关联资源&quot;">​</a></h2><ul><li><strong>主项目仓库</strong>：<a href="https://gitee.com/BearPlan/BearPlan.NET" target="_blank" rel="noreferrer">https://gitee.com/BearPlan/BearPlan.NET</a></li><li><strong>Core 独立仓库</strong>：<a href="https://gitee.com/BearPlan/BearPlan.NET.Core" target="_blank" rel="noreferrer">https://gitee.com/BearPlan/BearPlan.NET.Core</a></li><li><strong>开发文档</strong>：<a href="https://bear.js.org/" target="_blank" rel="noreferrer">https://bear.js.org/</a></li><li><strong>作者微信</strong>：Byte_Xiong（备注：框架）</li></ul>`,24)]))}const u=n(r,[["render",l]]);export{h as __pageData,u as default};
